private TreeNode<T> rotateRight(TreeNode<T> node) {
    //arian's initial thoughts
    //When performing a right rotation, we swap the node with its right child, then place the right child as the left child of the parent.
    //If the parent is null or has no right child, we return the node as is.
    //Otherwise, recursively callrotateRight on the right child's left subtree.
    if (node == null || node.right == null) {
        return node;
    }
    TreeNode<T> rightChild = node.right;
    TreeNode<T> newParent = rightChild.left;
    // Swap parents and children pointers
    node.right = newParent;
    if (newParent != null) {
        newParent.left = node;
    }
    return rightChild;
}

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Check if the directory exists
    if (new java.io.File(dir).exists()) {
        // Get an enumeration of URLs from the directory
        Enumeration<URL> urls = java.net.URLClassLoader.getSystemResources(dir);
        // Loop through the URLs and add them to the classpath vector
        while (urls.hasMoreElements()) {
            URL url = urls.nextElement();
            cpV.add(url);
        }
    } else {
        // Handle the case when the directory does not exist
        throw new IllegalArgumentException("Directory does not exist: " + dir);
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        java.nio.file.Files.walk(java.nio.file.Paths.get(dir))
                    .filter(Files::isRegularFile)
                    .map(path -> path.toURI().toURL())
                    .forEach(cpV::add);
    } catch (IOException e) {
        // Handle the error, for example, log a message or propagate it as a Runtime exception
        System.err.println("Error while adding files to the classpath: " + e.getMessage());
    }
}

