                } else if (file.getName().endsWith(".jar")) {
                   cpV.addElement(new URL("file:" + file.getAbsolutePath()));
                }
            }
        }
    } else {
        throw new IllegalArgumentException("Directory does not exist or is not a directory.");
    }
}

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    File f = new File(dir);
    ArrayList<String> jars = new ArrayList<>();
    if (!f.exists()) {
        throw new RuntimeException("Directory not found: " + dir);
    }
    try (Enumeration<java.nio.file.Path> fileEnum = Files.walk(f.toPath())) {
        collectPaths(fileEnum.map(java.nio.file.Path::toString)).forEach(jars::add);
    } catch (java.io.IOException e) {
        throw new RuntimeException("Error reading directory: " + dir, e);
    }
    for (String jar : jars) {
        try {
            JarFile jarFile = new JarFile(jar);
            Enumeration<java.util.jar.JarEntry> entries = jarFile.entries();
            while (entries.hasMoreElements()) {
                URL url = new URL(null, jar + '/' + entries.nextElement().getName());
                cpV.add(url);
            }
            jarFile.close();
        } catch (java.io.FileNotFoundException e) {
            // Skip non-Jar files
        } catch (java.io.IOException e) {
            throw new RuntimeException("Error reading jar file: " + jar, e);
        }
    }
}

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    File directory = new File(dir);
    if (!directory.exists()) {
        throw new IllegalArgumentException("The specified directory does not exist.");
    }

    try (Path startPath = Paths.get(directory.getAbsolutePath())) {
        Files.walk(startPath)
            .filter(path -> path.toFile().isJarFile())
            .map(path -> path.toUri().toURL())
            .forEach(cpV::add);
    } catch (IOException e) {
        throw new RuntimeException("Failed to read jar files in the directory.", e);
    }
}

