protected int findByte(byte value, int pos) {
    // Check if the buffer is null
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer is null");
    }
    // Check if the value is not specified
    if (value == null) {
        throw new IllegalArgumentException("Value is null");
    }
    // Check if the position is out of bounds
    if (pos < 0 || pos >= buffer.length) {
        throw new IllegalArgumentException("Position out of bounds");
    }
    // Base case: if the position is at the end, and the value matches, return that position
    if (pos == buffer.length && buffer[pos] == value) {
        return pos;
    }
    // Recursive case: move to the next position and try again
    int result = findByte(value, pos + 1);
    // If the value was found in the next position, return it
    if (result != -1) {
        return result;
    }
    // If the value was not found, return -1
    return -1;
}

protected int findByte(byte value, int pos) {
    if (value == null || pos < 0 || pos + value.length() > buffer.length) {
        throw new IllegalArgumentException("Invalid parameters");
    }
    try {
        for (int i = pos; i < pos + value.length(); i++) {
            if (buffer[i] == value[i - pos]) {
                return i;
            }
        }
        return -1;
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalStateException("Buffer is invalid");
    }
}

protected int findByte(byte value, int pos) {
    if (value == null || pos < 0) {
        // Handle invalid input
        throw new IllegalArgumentException("Value cannot be null and position must be non-negative.");
    }

    int end = Math.min(pos + 1, buffer.length);
    for (int i = pos; i < end; i++) {
        if (buffer[i] == value) {
            // Found the byte
            return i;
        }
    }

    // Byte not found
    return -1;
}

