    int size = 0;
    byte[] lengthBytes = schema.encodeLengthSchema(new ModifiedVarintSize().encode(message));
    out.write(lengthBytes);
    size += lengthBytes.length;
    buffer.prependPosition(size);

    int messageSize = schema.toByteArraySize(message, buffer);
    out.write(buffer.data(), buffer.position(), messageSize);
    size += messageSize;

    return size;
}

private static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Check if the message object is not null
    if (message == null) {
