    long currentStart = start;

    while (currentStart + FETCH_DATA_DURATION <= end) {
        timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
        currentStart += FETCH_DATA_DURATION;
    }

    if (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, end));
    }

    return timeRanges;
}

// Chunk short time ranges
if ((end - start) <= FETCH_DATA_DURATION) {
    return Arrays.asList(new TimeRange(start, end));
} else {
    long increment = FETCH_DATA_DURATION / 2;
    List<TimeRange> timeRanges = new ArrayList<>();
    while (end >= start) {
        timeRanges.add(new TimeRange(start, start + increment));
        start += increment;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        // Clamp start and end times to not exceed the FETCH_DATA_DURATION
        if (start > end) {
            start = end;
        }
        end = Math.min(end, System.currentTimeMillis() / 1000 + FETCH_DATA_DURATION);

        if (start >= end) {
            // No valid time range found
            throw new IllegalArgumentException("Start time is not before or equal to end time.");
        }

        if (start < 0) {
            // Start time is negative, indicating an invalid time range
            throw new IllegalArgumentException("Start time cannot be negative.");
        }

        // Convert start and end times to seconds
        long startTimeInSeconds = start / 1000;
        long endTimeInSeconds = end / 1000;

        TimeRange timeRange = new TimeRange(startTimeInSeconds, endTimeInSeconds);
        timeRanges.add(timeRange);

        return timeRanges;
    }

public List<TimeRange> buildTimeRanges(long start, long end) {
    //Calculate the duration to ensure it is smaller than FETCH_DATA_DURATION
    long duration = (end - start) + 1;
    if (duration >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Time range duration must be less than FETCH_DATA_DURATION (" + FETCH_DATA_DURATION + ")");
    }

    //Split the time ranges into smaller parts
    List<TimeRange> timeRanges = new ArrayList<>();
    for (long i = start; i <= end; i += FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(i, Math.min(i + FETCH_DATA_DURATION - 1, end)));
    }

    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
        if (start >= end) {
            throw new IllegalArgumentException("Start time must be less than end time.");
        }

        // Split the time range into segments that are less than FETCH_DATA_DURATION
        List<TimeRange> timeRanges = new ArrayList<>();
        while (start < end) {
            int duration = Math.min(FETCH_DATA_DURATION, end - start);
            timeRanges.add(new TimeRange(start, start + duration - 1));
            start += duration;
        }

        return timeRanges;
    }

