public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        int remainingLen = len;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if (c > 0xFF) {
                size += 3;
            } else if (c > 0x7F) {
                size += 2;
            } else {
                size += 1;
            }
            if ((char) c == -1) { // Sign Extension for negative values
                size++;
            }
            remainingLen--;
        }
        return size;
    }

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || str.length() == 0 || index < 0 || len < 1 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid parameters: str=null, str.length=0, index<0, len<1, or index+len>str.length()");
    }
    int actualSize = 0;
    for (int i = index; i < index + len; i++) {
        int c = (str.charAt(i) & 0xff00) >> 8;
        if ((c & 0xc0) == 0x80) {
            // Multi-byte UTF-8 character
            c = (str.charAt(i) & 0x007f) | ((str.charAt(i + 1) & 0xff00) >> 8);
            if ((c & 0xf0) == 0xe0) {
                c = (str.charAt(i) & 0x007f) | ((str.charAt(i + 1) & 0x007f) << 8) | ((str.charAt(i + 2) & 0xff00) >> 8);
            }
            actualSize += 2;
        } else {
            // Single-byte UTF-8 character
            actualSize += 1;
        }
    }
    return actualSize;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || index > str.length() || len <= 0 || len > str.length()) {
        throw new IllegalArgumentException("Invalid input. str must not be null, index must be within the bounds of the string, and len must be positive and within the bounds of the string.");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = str.charAt(i);
        if (b <= 0x7F) {
            size++;
        } else if (b >= 0xC2 && b <= 0xDF) {
            size += 2;
        } else if (b >= 0xE0 && b <= 0xED) {
            size += 3;
        } else if (b >= 0xF0 && b <= 0xF7) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character.");
        }
    }

    return size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null || index < 0 || len <= 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    int strLen = math.min(str.length(), index + len);
    int size = 0;

    while (index < strLen) {
        int codePoint = str.codePointAt(index);

        if (codePoint <= 0x7F) {
            index += 1;
            size += 1;
        } else if (codePoint <= 0x7FF) {
            index += 2;
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            index += 3;
            size += 3;
        } else if (codePoint <= 0x10FFFF) {
            index += 4;
            size += 4;
        } else {
            // Invalid UTF-8 character
            throw new IllegalArgumentException("Invalid UTF-8 character at index: " + index);
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index out of bounds");
    }

    if (len <= 0) {
        throw new IllegalArgumentException("Length must be Positive");
    }

    int size = 0;
    int i = index;

    while (i < index + len) {
        int firstByte = str.charAt(i++) & 0xFF;

        if ((firstByte & 0x80) == 0x00) {
            size++; // Single byte character
        } else if (((firstByte & 0xE0) == 0xC0) && i < index + len) {
            size += 2; // Two byte character
            int secondByte = str.charAt(i++) & 0xFF;
            if ((secondByte & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        } else if (((firstByte & 0xF0) == 0xE0) && i < index + len) {
            size += 3; // Three byte character
            int secondByte = str.charAt(i++) & 0xFF;
            int thirdByte = str.charAt(i++) & 0xFF;
            if (((secondByte & 0xC0) != 0x80) || ((thirdByte & 0xC0) != 0x80)) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        } else if (((firstByte & 0xF8) == 0xF0) && i < index + len) {
            size += 4; // Four byte character
            int secondByte = str.charAt(i++) & 0xFF;
            int thirdByte = str.charAt(i++) & 0xFF;
            int fourthByte = str.charAt(i++) & 0xFF;
            if (((secondByte & 0xC0) != 0x80) || ((thirdByte & 0xC0) != 0x80) || ((fourthByte & 0xC0) != 0x80)) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }

    return size;
}

