        return str == suffix;
    }

    if (str.length() < suffix.length()) {
        return false;
    }

    final int length = str.length() - suffix.length();
    final String sub = str.substring(length);

    if (!ignoreCase) {
        return sub.equals(suffix);
    }

    return sub.equalsIgnoreCase(suffix);
}

