        throw new IllegalArgumentException("Null URI");
    }

    PathSegmentImpl decoder = new PathSegmentImpl();
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = decode ? u.getPath().substring(1).replace(' ', '%20') : u.getPath();

    Map<String, PathSegmentImpl> segmentMap = new HashMap<>();
    segmentMap.put(".", new PathSegmentImpl());
    segmentMap.put("..", new PathSegmentImpl());

    if (path.isEmpty()) {
        return segments;
    }

    String[] segmentsArray = path.split("/");
    for (String segment : segmentsArray) {
        if (segment.length() == 0 || segment.equals(".")) {
            continue;
        } else if (segment.equals("..") && !segmentMap.isEmpty() && !segmentMap.get("..").isRoot()) {
            segmentMap.get("..").pop();
        } else {
            PathSegmentImpl newSegment = new PathSegmentImpl(segment);
            segmentMap.put(segment, newSegment);
            segments.add(newSegment);
        }
    }

    return segments.isEmpty() ? List.of(new PathSegmentImpl("#")) : segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null || u.getPath() == null) {
        throw new IllegalArgumentException("Invalid URI");
    }

    // Trim leading '/'
    if (u.getPath().startsWith("/")) {
        u = new URI(u.getScheme(), u.getHost(), u.getPort(), u.getQuery(), u.getFragment(), u.getPath().substring(1));
    }

    String[] segments = u.getPath().split("/");
    List<PathSegmentImpl> pathSegments = new ArrayList<>(segments.length);

    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue;
        }
        PathSegmentImpl ps = new PathSegmentImpl(segment, decode);
        pathSegments.add(ps);
    }

    return pathSegments;
}

