    double midpoint = width / 2.0;
    Box2D box1 = new Box2D(box.getLowerX(), box.getLowerY(), midpoint, box.getUpperY());
    Box2D box2 = new Box2D(midpoint, box.getLowerY(), box.getUpperX(), box.getUpperY());

    return new Pair<>(box1, box2);
