public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double xPosition = box.getX();
    double width = box.getWidth();
    if (Math.abs(width) < EPSILON) {
        throw new IllegalArgumentException("Box width is zero.");
    }
    double halfWidth = width / 2;

    Pair<Box2D, Box2D> result = new Pair<>();
    result.first = new Box2D(xPosition, box.getY(), halfWidth, box.getHeight());
    result.second = new Box2D(xPosition + halfWidth, box.getY(), halfWidth, box.getHeight());

