public static int writeTo(final DataOutput out, final LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    int totalSize = 0;
    Node current = node.head;
    while (current != null) {
        byte[] bytes = current.data;
        out.write(bytes);
        totalSize += bytes.length;
        current = current.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null || node.getData() == null) {
        throw new IllegalArgumentException("Node or data cannot be null");
    }

    int totalSize = 0;
    // Assuming each byte of LinkedBuffer's data is written to DataOutput
    while (node.getData() != null) {
        out.writeByte(node.getData()[0]);
        totalSize += 1;
        node = node.getNext();
    }
    return totalSize;
}

