public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1) {
        throw new IllegalArgumentException("Capacity must be greater than 1");
    }

    if (desiredCapacity < 200) {
        return Math.max(2, desiredCapacity);
    }

    int number = desiredCapacity;
    boolean isPrime = false;

    // Check divisibility from 2 to square root of the number
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            isPrime = false;
            break;
        }
        isPrime = true;
    }

    if (isPrime) {
        return number;
    }

    // If not prime, find the next prime number
    while (!isPrime) {
        number++;
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                break;
            }
            isPrime = true;
        }
    }

    return number;
}

