    // ETF (Euler's totient function) calculation
    BigInteger phi = BigInteger.valueOf(desiredCapacity).subtract(BigInteger.ONE);
    for (int i = 2; i * i <= desiredCapacity; i++) {
        if (desiredCapacity % i == 0) {
            phi = phi.subtract(BigInteger.valueOf(phi.mod(BigInteger.valueOf(i)).intValue()));
        }
    }

    // The next prime number is approximately Phi(desiredCapacity) times the largest prime below sqrt(desiredCapacity)
    int largestPrimeBelowSqrt = largestPrimeBelow(Math.sqrt((double) desiredCapacity));
    if (largestPrimeBelowSqrt > 1) {
        BigInteger product = BigInteger.valueOf(largestPrimeBelowSqrt)
                .multiply(BigInteger.valueOf(phi.intValue()))
                .divide(BigInteger.valueOf(largestPrimeBelowSqrt), 0, RoundingMode.HALF_UP);
        return product.intValue();
    } else {
        return desiredCapacity;
    }
}

