public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder buffer = new StringBuilder();
    int i = 0;
    int len = str.length();
    while (i < len) {
        if (str.charAt(i) == '\\') {
            i++;
            if (i == len) {
                continue; // Ignore escaped null character
            }
            switch (str.charAt(i)) {
                case 'n':
                    buffer.append('\n');
                    break;
                case 't':
                    buffer.append('\t');
                    break;
                case 'r':
                    buffer.append('\r');
                    break;
                case '\'"':
                    buffer.append('\"');
                    break;
                case '\\':
                    buffer.append('\\');
                    break;
                default:
                    // Handle other escape sequences as needed
                    throw new IllegalArgumentException("'\\' escape sequence not supported");
            }
        } else {
            buffer.append(str.charAt(i));
        }
        i++;
    }
    return buffer.toString();
}

public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= len) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char esc = str.charAt(i);
            switch (esc) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '\"':
                    result.append('"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                default:
                    throw new Exception("Unsupported escape sequence: " + esc);
            }
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

