final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Ensure the buffer is sufficient
    if (charBuffer.length < 4) {
        throw new IllegalArgumentException("The provided character buffer is too small to store a string length.");
    }

    // Read the byte length of the UTF-8 string
    int byteLength = Integer.parseInt(new String(charBuffer, 0, 4), 16);

    // Ensure there are enough characters to fill the string length
    if (charBuffer.length < byteLength) {
        throw new IllegalArgumentException("The provided character buffer is too small to store the string.");
    }

    // Read the actual UTF-8 string
    int pos = 4;
    for (int i = 0; i < byteLength; i++) {
        charBuffer[pos++] = (char) (charBuffer[pos - 3] << 4 | charBuffer[pos - 2] >>> 2);
    }

    // Trim any trailing null bytes
    while (pos < charBuffer.length && charBuffer[pos - 1] == 0) {
        pos--;
    }

    return new String(charBuffer, 0, pos);
}

public String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) throws IndexOutOfBoundsException {
    if (constantPoolEntryIndex < 0) {
        throw new IndexOutOfBoundsException("Invalid constant pool entry index.");
    }

    final int utf8LengthIndex = constantPoolEntryIndex << 1 + 1;
    final int utf8Length = constantPoolEntryBuffer[utf8LengthIndex];

    // Ensure the char buffer is large enough to hold the UTF-8 string
    if (charBuffer.length < utf8Length + 2) {
        throw new IllegalArgumentException("Char buffer is too small to hold the UTF-8 string.");
    }

    final char[] bytes = new char[utf8Length];

    // Read the bytes of the UTF-8 string
    for (int i = 0; i < utf8Length; i++) {
        int b = constantPoolEntryBuffer[i + uttf8LengthIndex];
        if (b < 128) {
            bytes[i] = (char) b;
        } else {
            int b1 = constantPoolEntryBuffer[i + uttf8LengthIndex + 1];
            int b2 = constantPoolEntryBuffer[i + uttf8LengthIndex + 2];
            bytes[i] = (char) ((b1 & 0x1F) << 6 | (b2 & 0x3F) << 0);
        }
    }

    // Decode the UTF-8 bytes into a string
    return new String(bytes);
}

