        throw new IllegalArgumentException("constantPoolEntryIndex must be non-negative");
    }
    int constantPoolEntryOffset = classFileBuffer.getInt(constantPoolEntryIndex * ConstantPoolEntry.OFFSET_BASE);
    int stringIndex = classFileBuffer.getInt(constantPoolEntryOffset + ConstantPoolEntry.OFFSET_STRING_INDEX);
    if (stringIndex < 0 || stringIndex >= classFileBuffer.length() - ConstantPoolEntry.OFFSET_STRING_TABLE) {
        throw new IllegalArgumentException("StringIndex is invalid");
    }

    int stringTableOffset = classFileBuffer.getInt(constantPoolEntryOffset + ConstantPoolEntry.OFFSET_STRING_TABLE);
    charBuffer = Arrays.copyOf(classFileBuffer, classFileBuffer.length);
    int index = 0;
    int offset = stringTableOffset;
    byte mark = 0;
    try {
        while (charBuffer[offset] != mark && charBuffer[offset] != ']') {
            charBuffer[index++] = charBuffer[offset++];
        }
        charBuffer[index++] = mark;
        return new String(charBuffer, 0, index);
    } finally {
        Arrays.fill(charBuffer, stringTableOffset, index + 1, (byte) 0);
    }
}

