            if (currentNode == detachableFace.prev(narrow, node)) {
                circulator = new OuterFaceCirculator(detachableFace.faceNext(currentNode, true)); // Move to next face
                circulator.currentNode = circulator.currentNode == null ? detachableFace.prev(narrow, node) : circulator.currentNode;
            } else if (currentNode == detachableFace.next(narrow, node)) {
                circulator = new OuterFaceCirculator(detachableFace.facePrev(currentNode, true)); // Move to previous face
                circulator.currentNode = circulator.currentNode == null ? detachableFace.next(narrow, node) : circulator.currentNode;
            }
        } else if (dir == 1 || dir == 3) {
            // Move to the adjacent side
            if (currentNode == narrow.faceNext(currentNode, stop)) {
                circulator = new OuterFaceCirculator(detachableFace.facePrev(currentNode, true)); // Move to previous face
                circulator.currentNode = circulator.currentNode == null ? narrow.faceNext(currentNode, stop) : circulator.currentNode;
            } else if (currentNode == narrow.facePrev(currentNode, stop)) {
                circulator = new OuterFaceCirculator(detachableFace.faceNext(currentNode, true)); // Move to next face
                circulator.currentNode = circulator.currentNode == null ? narrow.facePrev(currentNode, stop) : circulator.currentNode;
            }
        }
