private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result = new OuterFaceCirculator();
    result.cur = start;

    while (result.cur != null) {
        if (predicate.test(result.cur)) {
            result.stop = stop;
            return result;
        }
        if (dir == 0 && result.cur.hasLeftNeighbor()) {
            result.cur = result.cur.leftNeighbor();
        } else if (dir == 1 && result.cur.hasRightNeighbor()) {
            result.cur = result.cur.rightNeighbor();
        } else if (dir == 2 && result.cur.hasFrontNeighbor()) {
            result.cur = result.cur.frontNeighbor();
        } else if (dir == 3 && result.cur.hasBackNeighbor()) {
            result.cur = result.cur.backNeighbor();
        } else {
            // Handle the case where there are no neighbors in the current direction
            result.cur = null;
            break;
        }
    }

    result.stop = stop;
    return result;
}

