    if (str == null || leadingCharacter == 0) {
        throw new IllegalArgumentException("Input string or leading character is null or the leading character is 0.");
    }
    StringBuilder result = new StringBuilder();
    boolean startTrimming = true;
    for (char c : str.toCharArray()) {
