public static String trimLeadingCharacter(String str, char leadingCharacter) {
    if (str == null) {
        throw new NullPointerException("str cannot be null");
    }
    if (leadingCharacter == '\0') {
        throw new IllegalArgumentException("leadingCharacter cannot be empty or null");
    }

    int index = 0;
    int length = str.length();

    // Trim leading characters
    while (index < length && str.charAt(index) == leadingCharacter) {
        index++;
    }

    // Return a substring starting from the first non-trimmed position
    if (index == length) {
        return ""; // Return an empty string if all characters are leading ones
    }
    return str.substring(index);
}

