public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {

    // Handle empty list input
    if (bounds.isEmpty()) {
        return Pair.of(new ArrayList<>( bounds.size()), 0L);
    }

    // Compute prefix sums
    List<Integer> prefixSums = new ArrayList<>(bounds.size());
    prefixSums.add(bounds.get(0));
    long totalSum = prefixSums.get(prefixSums.size() - 1);

    for (int i = 1; i < bounds.size(); i++) {
        prefixSums.add(prefixSums.get(i - 1) + bounds.get(i));
        totalSum += bounds.get(i);
    }

    // Compute suffix sums
    List<Integer> suffixSums = new ArrayList<>(prefixSums.size());
    suffixSums.set(prefixSums.size() - 1, totalSum);
    for (int i = prefixSums.size() - 2; i >= 0; i--) {
        suffixSums.set(i, prefixSums.get(i + 1));
    }

    return Pair.of(suffixSums, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty.");
    }

    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSum.add(totalSum);
        totalSum += bounds.get(i);
    }

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffs = new ArrayList<>();
        long totalSum = 0;

        // Compute suffix sum
        for (int i = bounds.size() - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            suffs.add(totalSum);
        }

        Collections.reverse(suffs); // Reverse the suffix sum list
        return new Pair<>(suffs, totalSum);
    }

