public ByteVector putInt(final int intValue) {
    if (intValue < 0 || intValue > 255) {
        throw new IllegalArgumentException(" intValue must be in the range of 0 to 255");
    }

    // Determine the size of the byte array based on the integer value
    int size = 1; // For the integer itself
    if (intValue > 255) {
        size += 1; // For the additional byte needed if intValue > 255
    }

    // Extend the byte array if necessary
    if (data.length < size) {
        data = new byte[size];
    }

    // Write the integer value into the byte array
    data[data.length - 1 - size] = (byte) (intValue & 0xFF);

    // If intValue > 255, write the additional byte
    if (intValue > 255) {
        data[data.length - 2] = (byte) ((intValue >> 8) & 0xFF);
    }

    return this;
}

