public void putInt(int intValue) {
    byte[] data = new byte[bytes.length];
    for (int i = 0; i < 4; i++) {
        int bitPosition = (3 - i) * 8;
        boolean highBit = (intValue >>> bitPosition) & 1;
        boolean lowBit = (intValue >>> (bitPosition - 1)) & 1;
        if (highBit) {
            data[i / 8] |= (1 << (i % 8));
        }
        if (lowBit) {
            data[i / 8] |= (1 << ((i + 1) % 8));
        }
    }
    bytes = new byte[data.length + (5 - bytes.length % 5) % 5];
    System.arraycopy(data, 0, bytes, 5 - bytes.length % 5, data.length);
}

