public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if the typeVariable is null
    if (typeVariable == null) {
        throw new IllegalArgumentException("typeVariable cannot be null");
    }

    // Handle the case where typeVariable has no bounds
    if (typeVariable.getBounds().length == 0) {
        return Unknown.class;
    }

    // Resolve the bounds by substituting them with their actual types
    for (Type bound : typeVariable.getBounds()) {
        // Check if the bound is itself a type parameter
        if (bound instanceof TypeVariable<?>) {
            typeVariable = (TypeVariable<?>) bound;
        }
        // Replace the bounds in typeVariable with their actual types
        typeVariable = bound;
    }

    return typeVariable;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        // Attempt to resolve the bound
        Type bound = typeVariable.getBounds()[0];
        // Check if the bound is null and return Unknown.class
        if (bound == null) {
            return Unknown.class;
        } else {
            return bound;
        }
    } catch (IndexOutOfBoundsException e) {
        // Handle the case where there is no bound (default to Unknown.class)
        return Unknown.class;
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new IllegalArgumentException("TypeVariable cannot be null");
    }

    Type superType = typeVariable.getUpperBound();
    return superType != null ? superType : Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new NullPointerException("TypeVariable cannot be null");
    }
    return typeVariable.getBounds().length > 0 ? typeVariable.getBounds()[0] : Unknown.class;
}

public static Unknown resolveBound(TypeVariable<?> typeVariable) throws IllegalArgumentException {
    Type.GenericDeclaration genericDeclaration = typeVariable.resolve();
    if (genericDeclaration == null) {
        return Unknown.class;
    }
    Type resolvedType = genericDeclaration.getTypeBounds()[0];
    if (resolvedType == null) {
        return Unknown.class;
    }
    return TypeToken.of(resolvedType).getRawClass();
}

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return true; // An empty graph is considered a clique by definition
    }

    // Check if every vertex is adjacent to every other vertex in the set of vertices
    for (V vertex : vertices) {
        if (vertices.contains(vertex)) {
            continue; // Skip the vertex itself
        }

        for (V other : vertices) {
            if (vertex.equals(other)) {
                continue; // Skip the same vertex again
            }
            if (!graph.hasEdge(vertex, other)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty set isn't considered a clique, by definition
    }

    int numVertices = vertices.size();
    for (int i = 0; i < numVertices; i++) {
        V vertex1 = vertices.iterator().next();
        vertices.remove(vertex1);

        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false; // Found a non-edge, not a clique
            }
        }

        vertices.add(vertex1); // Restore vertex1 to original set
    }

    return true; // All adjacent vertices are neighbors
}

