        for (V vertex : vertices) {
            verticesInClique.put(vertex, false);
        }

        // Iterate through each edge in the original graph
        for (E edge : graph.edges()) {
            V srcVertex = graph.getEdgeSource(edge);
            V dstVertex = graph.getEdgeTarget(edge);

            // Mark both vertices in the original graph as being in the clique (even if they are not in the given vertices)
            verticesInClique.put(srcVertex, true);
            verticesInClique.put(dstVertex, true);

            // If the edge connects a vertex in the given vertices to a vertex not in the given vertices, the graph is not a clique
            if (vertices.contains(srcVertex) && !vertices.contains(dstVertex)) {
                return false;
            } else if (vertices.contains(dstVertex) && !vertices.contains(srcVertex)) {
                return false;
            }
        }

        // If no edge breaks the clique, all vertices in the given vertices are connected to each other, making the graph a clique
        return true;
    }

