public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    StringBuilder fullPath = new StringBuilder(path);
    int pos = path.lastIndexOf('/');

    // If path contains no directory separator, add root
    if (pos == -1) {
        fullPath.append("/");
    } else {
        fullPath.append(relativePath);
    }

    return fullPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null.");
    }

    // Splitting the original path by '/' and getting the last part
    String[] parts = path.split("\\\\");
    String result = parts[parts.length - 1];

    // Concatenating the result with the relative path
    return result + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    StringBuilder result = new StringBuilder(path);
    if (!relativePath.isEmpty()) {
        String[] relativeSplit = relativePath.split("/");
        for (String s : relativeSplit) {
            if (s.startsWith("..")) {
                if (result.length() > 0) {
                    result.setLength(result.length() - 1); // Go up one directory level if possible
                }
            } else if (!s.isEmpty()) {
                result.append("/");
                result.append(s);
            }
        }
    }
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    // Check for null or empty inputs
    if(path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()){
        throw new IllegalArgumentException("Both path and relativePath must be non-null and non-empty strings.");
    }

    // Normalize the path
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Build the full path
    StringBuilder fullPath = new StringBuilder(path);
    if(!relativePath.isEmpty()){
        int segments = relativePath.contains("\\\\") ? relativePath.split("\\\\").length - 1 : relativePath.split("/").length - 1;
        for(int i = 0; i < segments; i++){
            fullPath.append("/");
        }
    }

    return fullPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path cannot be null");
    }

    return new File(path, relativePath).getPath();
}

