        if (array[i] == null) {
            String[] resultArray = new String[array.length - 1];
            for (int j = 0; j < i; ++j) {
                resultArray[j] = tmpArray[j];
            }
            for (int j = i; j < array.length - 1; ++j) {
                resultArray[j + 1] = tmpArray[j];
            }
            tmpArray = resultArray;
        }
    }
    return tmpArray;
}

