    int tag = -1; // Initially set to an invalid value
    int value = 0;  // Temporarily store the current value in the tag
    int sign = -1;  // Determine the sign of the tag

    // Read the first byte of the tag
    int b1 = inputStream.read();
    if (b1 < 0) {
        throw new IOException("End of stream reached while reading tag"); // Throw an exception if end of stream is reached
    }

    // Determine if the tag is positive or negative based on the most significant bit
    if (b1 > 127) {
        sign = -1; // Negative tag if the most significant bit is set
        b1 -= 128; // Adjust the byte value to adjust for sign
    }

    // Read the second byte of the tag (if present)
    if (inputStream.available() > 0) {
        int b2 = inputStream.read();
        if (b2 < 0) {
            throw new IOException("End of stream reached while reading tag"); // Throw an exception if end of stream is reached
        }

        // Combine the two bytes to form the complete tag
        tag = ((b1 << 7) | b2);
    } else {
        tag = b1; // If only one byte is available, set it as the tag value
    }

    return tag * sign; // Return the tag value adjusted for its sign
}

public int readTag() throws IOException {
    if (stream == null || stream.available() == 0) {
        return 0;
    }

    int tag = stream.read();
    if (tag == 0) {
        stream.mark(1);
        int two = stream.read();
        if (two == 0) {
            stream.reset();
            return 0;
        } else {
            stream.reset();
            tag = (two << 8 - 1) | tag;
        }
    } else if (tag >= 128) {
        tag ^= 0xc0;
        int length = 1;
        while ((tag & 0x80) != 0) {
            tag >>= 7;
            length++;
        }
        for (int i = 0; i < length; i++) {
            tag = (tag & 0x7F) | ((stream.read() & 0xFF) << (7 * i));
        }
    }

    return tag;
}

